"""CRC16 used by the device's attribute/TLV layer.

Tables lifted from the vendor SDK (libcfdlink.so @ 0x1a825 / 0x1a925) because the
polynomial is non-standard. Verified against device replies and app writes:
  name reply  c9 64 | sn reply f0 05 | gain 18 dB write c0 5c | attr 0x12 write 60 55
"""
from __future__ import annotations

LO = bytes.fromhex("")
HI = bytes.fromhex("")


def crc16(data: bytes) -> int:
    c = 0
    for b in data:
        i = (c ^ b) & 0xFF
        c = ((c >> 8) ^ (HI[i] << 8) ^ LO[i]) & 0xFFFF
    return c


def crc16_bytes(data: bytes) -> bytes:
    return crc16(data).to_bytes(2, "little")
